Signed-off-by: Anthony Liguori <aliguori@us.ibm.com>

Here is the root cause:
The bug was caused by the `rom_copy` function skipping ROM entries with a `datasize` of 0 due to the check for `!rom->data`, which incorrectly prevented the function from processing valid ROM entries that had no data to copy. This led to multiboot kernels not being loaded correctly when they contained segments with a file size of 0.

Here is the patch:
  */
 int rom_copy(uint8_t *dest, hwaddr addr, size_t size)
 {
     hwaddr end = addr + size;
     uint8_t *s, *d = dest;
     size_t l = 0;
     Rom *rom;

     QTAILQ_FOREACH(rom, &roms, next) {
         if (rom->fw_file) {
             continue;
         }
         if (rom->addr + rom->romsize < addr) {
             continue;
         }
         if (rom->addr > end) {
             break;
         }
-        if (!rom->data) {
-            continue;
-        }

         d = dest + (rom->addr - addr);
         s = rom->data;
         l = rom->datasize;

         if ((d + l) > (dest + size)) {
             l = dest - d;
         }

-        memcpy(d, s, l);
+        if (l > 0) {
+            memcpy(d, s, l);
+        }

         if (rom->romsize > rom->datasize) {
             /* If datasize is less than romsize, it means that we didn't
              * allocate all the ROM because the trailing data are only zeros.
              */

             d += l;
             l = rom->romsize - rom->datasize;

             if ((d + l) > (dest + size)) {
                 /* Rom size doesn't fit in the destination area. Adjust to avoid
                  * overflow.
                  */
                 l = dest - d;
             }

             if (l > 0) {
                 memset(d, 0x0, l);
             }
         }
     }

     return (d + l) - dest;
 }



